import * as T from './vendor/three.module.js';
import {ESTATE_PLOTS as P} from './estate-plots.mjs';
import {buildAlpineRoof} from './alpine-roof.mjs';
// Real constructed additions; unbuilt sites remain open meadow, never placeholder buildings.
export function createEstateDevelopment({scene,height,colliders,interactive,navigationTargets,animated,materials:M,label}){
 const groups={},owned=[],doors=[],upperParts=[],roofParts=[];let previous=null;
 const mesh=(geo,m,p)=>{const o=new T.Mesh(geo,m);o.castShadow=o.receiveShadow=true;p.add(o);return o;};
 function box(w,h,d,m,x,y,z,p){const o=mesh(new T.BoxGeometry(w,h,d),m,p);o.position.set(x,y,z);return o;}
 function rod(a,b,r,m,p){const u=new T.Vector3(...a),v=new T.Vector3(...b),d=v.clone().sub(u),o=mesh(new T.CylinderGeometry(r*.8,r,d.length(),10),m,p);o.position.copy(u.add(v).multiplyScalar(.5));o.quaternion.setFromUnitVectors(new T.Vector3(0,1,0),d.normalize());return o;}
 function group(id,p=P[id]){const g=new T.Group();g.position.set(p.x,height(p.x,p.z),p.z);g.userData.kind='development-'+id;scene.add(g);groups[id]=g;g.visible=false;return g;}
 function window(x,y,z,g){box(1.1,1.25,.1,M.beam,x,y,z,g);box(.91,1.04,.12,M.glass,x,y,z+.02,g);box(.055,1.1,.15,M.cream,x,y,z+.07,g);box(1,.055,.15,M.cream,x,y,z+.07,g);for(const side of[-1,1])box(.28,1.18,.12,M.shutter,x+side*.72,y,z,g);box(1.28,.22,.3,M.timber,x,y-.69,z+.1,g);for(let j=0;j<7;j++){const flower=mesh(new T.SphereGeometry(.06,6,5),new T.MeshStandardMaterial({color:j%2?'#b9584a':'#d8b65c'}),g);flower.position.set(x-.5+j*.17,y-.55,z+.2);}}
 function table(x,z,g){box(1.5,.09,1,M.timber,x,.84,z,g);for(const dx of[-.55,.55])for(const dz of[-.32,.32])box(.065,.8,.065,M.beam,x+dx,.4,z+dz,g);for(const side of[-1,1]){box(1.6,.09,.35,M.timber,x,.49,z+side*.77,g);for(const dx of[-.6,.6])box(.08,.45,.25,M.beam,x+dx,.23,z+side*.77,g);}}
 function building(id,levels=1){const p=P[id],g=group(id),w=p.w,d=p.d;
 box(w,.38,d,M.stone,0,.19,0,g);box(w-.3,2.7*levels,d-.3,M.timber,0,.38+1.35*levels,0,g);
 for(const side of[-1,1]){for(let i=0;i<levels;i++){window(side*w*.27,1.75+i*2.7,d/2-.07,g);}box(.17,2.7*levels,.2,M.beam,side*(w/2-.12),.4+1.35*levels,d/2,g);}
 box(1.25,2.2,.16,M.beam,0,1.48,d/2+.04,g);box(.92,1.83,.18,M.shutter,0,1.42,d/2+.1,g);label(p.title,0,2.85,d/2+.16,Math.min(3,w*.55),g);
 const roof=new T.Group();g.add(roof);buildAlpineRoof(roof,M,{halfWidth:w/2+.35,halfDepth:d/2+.4,ridge:4.9+(levels-1)*2.7,eave:3.2+(levels-1)*2.7,rows:12,columns:12,kind:'development'});
 // Gable closes the timber shell beneath the sloping roof.
 for(const z of[-d/2,d/2]){const sh=new T.Shape();sh.moveTo(-w/2,3.05+(levels-1)*2.7);sh.lineTo(0,4.9+(levels-1)*2.7);sh.lineTo(w/2,3.05+(levels-1)*2.7);sh.closePath();const o=mesh(new T.ShapeGeometry(sh),M.timber,roof);o.position.z=z;}
 owned.push({id,collider:{x:p.x,z:p.z,w:w+.15,d:d+.15}});
 const door={id:'development-'+id,...p.entry,range:2.6,name:p.title+' · Betrieb führen',estateBusiness:true,g};interactive.push(door);doors.push(door);g.userData.navigationId=door.id;
 return{g,roof};}
 const restaurant=building('restaurant');roofParts.push(restaurant.roof);const upper=new T.Group();upper.position.y=3.05;restaurant.g.add(upper);box(P.restaurant.w-.3,2.7,P.restaurant.d-.3,M.timber,0,1.35,0,upper);for(const x of[-2,2])window(x,1.4,2.94,upper);upperParts.push(upper);
 building('restaurantPlus');building('hotel',2);
 // First hut upgrade stays attached to the original home.
 const hut=group('hut',{x:-16,z:-3.7});for(const x of[-3,3])rod([x,0,0],[x,2.7,0],.085,M.beam,hut);const canopy=box(7,.14,1.7,M.roof,0,2.7,-.3,hut);canopy.rotation.x=-.1;box(2.4,.12,.55,M.timber,-2,.6,0,hut);for(const x of[-2.8,-1.2])box(.14,.55,.4,M.beam,x,.28,0,hut);for(const x of[-3.2,3.2]){box(.65,.4,.6,M.timber,x,.2,0,hut);for(let j=0;j<5;j++){const o=mesh(new T.SphereGeometry(.09,8,6),M.shutter,hut);o.position.set(x+(j-2)*.12,.48,0);}}
 // Outdoor family and wellness decks are accessible surfaces.
 const spa=group('spa');box(7,.18,6,M.timber,0,.09,0,spa);const tub=mesh(new T.CylinderGeometry(1.65,1.5,.85,48,1,true),M.timber,spa);tub.position.y=.55;const waterMat=new T.MeshStandardMaterial({color:'#84c4c5',roughness:.15,metalness:.2,transparent:true,opacity:.85});const water=mesh(new T.CircleGeometry(1.5,48),waterMat,spa);water.rotation.x=-Math.PI/2;water.position.y=.92;const rim=mesh(new T.TorusGeometry(1.57,.1,10,48),M.cream,spa);rim.rotation.x=Math.PI/2;rim.position.y=.95;for(let i=0;i<12;i++){const b=mesh(new T.SphereGeometry(.025+(i%3)*.012,6,5),M.cream,spa);animated.push(t=>{b.position.set(Math.sin(i*2.4+t*.3)*1.2,.93+Math.sin(t*2+i)*.035,Math.cos(i*2.4+t*.3)*1.2);});}owned.push({id:'spa',collider:{type:'circle',x:P.spa.x,z:P.spa.z,r:1.7}});
 const play=group('playground');for(const x of[-2.3,2.3])for(const z of[-.8,.8])rod([x,0,z],[x,2.7,0],.08,M.beam,play);rod([-2.5,2.7,0],[2.5,2.7,0],.09,M.timber,play);for(const x of[-1,1]){const swing=new T.Group();swing.position.set(x,2.6,0);play.add(swing);for(const dx of[-.23,.23])rod([dx,0,0],[dx,-1.9,0],.017,M.beam,swing);box(.7,.08,.32,M.timber,0,-1.9,0,swing);animated.push(t=>swing.rotation.x=Math.sin(t*.8+x)*.12);}box(2,.16,2,M.timber,2,.08,1.2,play);box(1.8,.08,1.8,new T.MeshStandardMaterial({color:'#cfbf8e'}),2,.18,1.2,play);
 const pasture=group('pasture');for(const z of[-P.pasture.d/2,P.pasture.d/2])for(let x=-4.4;x<=4.4;x+=1.1){const y=height(P.pasture.x+x,P.pasture.z+z)-pasture.position.y;box(.1,1.1,.1,M.timber,x,y+.55,z,pasture);if(x<4)for(const yy of[.4,.85])rod([x,y+yy,z],[x+1.1,height(P.pasture.x+x+1.1,P.pasture.z+z)-pasture.position.y+yy,z],.045,M.beam,pasture);}for(const x of[-4.4,4.4])for(let z=-7;z<7;z+=1.4){if(x<0&&Math.abs(z)<2)continue;const y=height(P.pasture.x+x,P.pasture.z+z)-pasture.position.y;box(.1,1.1,.1,M.timber,x,y+.55,z,pasture);for(const yy of[.4,.85])rod([x,y+yy,z],[x,height(P.pasture.x+x,P.pasture.z+z+1.4)-pasture.position.y+yy,z+1.4],.045,M.beam,pasture);}box(1.6,.5,.8,M.stone,2,.25,-3,pasture);box(1.4,.03,.6,waterMat,2,.51,-3,pasture);
 for(const z of[-7,7])owned.push({id:'pasture',collider:{x:P.pasture.x,z:P.pasture.z+z,w:8.9,d:.14,penFence:true}});owned.push({id:'pasture',collider:{x:P.pasture.x+4.4,z:P.pasture.z,w:.14,d:14,penFence:true}});for(const side of[-1,1])owned.push({id:'pasture',collider:{x:P.pasture.x-4.4,z:P.pasture.z+side*4.6,w:.14,d:4.8,penFence:true}});
 const silo=group('silo');const body=mesh(new T.CylinderGeometry(1.55,1.55,3.3,32),M.timber,silo);body.position.y=1.65;for(const y of[.4,1.6,2.9]){const hoop=mesh(new T.TorusGeometry(1.56,.035,8,48),M.beam,silo);hoop.rotation.x=Math.PI/2;hoop.position.y=y;}const cap=mesh(new T.ConeGeometry(1.9,1,32),M.roof,silo);cap.position.y=3.8;owned.push({id:'silo',collider:{type:'circle',x:P.silo.x,z:P.silo.z,r:1.7}});label('Heuvorrat',0,2,1.6,1.3,silo);
 const tools=group('tools');box(1.4,.12,.65,M.timber,0,.9,0,tools);for(const x of[-.55,.55])box(.08,.9,.08,M.beam,x,.45,0,tools);rod([-.5,.9,0],[.5,1.9,0],.025,M.timber,tools);const blade=mesh(new T.TorusGeometry(.35,.025,5,24,Math.PI),M.stone,tools);blade.position.set(.5,1.9,0);table(-2,1.4,restaurant.g);
 for(const id of['spa','playground','pasture','silo','tools']){const p=P[id],n={id:'development-'+id,...p.entry,name:p.title+' · Ausbau & Betrieb',range:2.6,estateBusiness:true,g:groups[id]};interactive.push(n);doors.push(n);groups[id].userData.navigationId=n.id;}
 return{groups,plots:P,sync(s){const signature=Object.keys(s.estate.built).filter(k=>s.estate.built[k]).join(',');if(signature===previous)return;previous=signature;for(const[id,g]of Object.entries(groups))g.visible=!!s.estate.built[id];for(let i=navigationTargets.length-1;i>=0;i--)if(Object.values(groups).includes(navigationTargets[i]))navigationTargets.splice(i,1);for(const g of Object.values(groups))if(g.visible)navigationTargets.push(g);upperParts.forEach(g=>g.visible=!!s.estate.built.upperfloor);roofParts.forEach(g=>g.position.y=s.estate.built.upperfloor?2.7:0);for(let i=colliders.length-1;i>=0;i--)if(colliders[i].estateDevelopment)colliders.splice(i,1);for(const{id,collider}of owned)if(s.estate.built[id])colliders.push({...collider,estateDevelopment:true});for(const n of doors)n.disabled=!s.estate.built[n.id.replace('development-','')];}};
}
